import { useParams } from 'react-router-dom'
import Footer from '../../components/Footer'
import Banner from '../../components/Banner'
import Pratos from '../../models/Pratos'
import HeaderAlternativo from '../../components/Header/HeaderAlternativo'
import pizza from '../../assets/pratos/2ndPage/pizzamarguerita.png'
import ProductsList from '../../components/ProductsList'

// Lista de pratos para a nova página
export const sndPage: Pratos[] = [
  {
    id: 1,
    title: 'Pizza Marguerita',
    nota: 10,
    description:
      'A clássica Marguerita: molho de tomate suculento, mussarela derretida, manjericão fresco e um toque de azeite. Sabor e simplicidade!',
    image: pizza, // Remova as aspas extras
    infos: ['Destaque da Semana', 'Italiana'] // Adicione a propriedade `infos`
  }
  // Outros pratos...
]

const Prato1 = () => {
  const { pratoId } = useParams<string>() // Especificando que pratoId será do tipo string

  // Busca o prato específico na lista `sndPage`
  const prato = sndPage.find(
    (prato) => prato.id === parseInt(pratoId || '', 10)
  )

  if (!prato) {
    return <div>Prato não encontrado!</div> // Caso não encontre o prato, exibe uma mensagem de erro
  }

  // Passar a primeira informação de 'infos' como 'info'
  const info = prato.infos ? prato.infos[0] : ''

  return (
    <>
      <HeaderAlternativo />
      <Banner image={prato.image} title={prato.title} info={info} />{' '}
      {/* Passando 'info' */}
      <ProductsList pratos={sndPage} title="" background="gray" />
      <Footer />
    </>
  )
}

export default Prato1
